-- YG-1365: rapor kataloğu durumlarının sözlük tanımları; "Çıkarıldı" iki kayıt türünde aynı genel anlamla tanımlanır.
UPDATE durum_sozlugu SET is_anlami = 'Kayıt ilgili listeden gerekçeyle çıkarıldı; listenin sonucuna dahil edilmez.' WHERE durum = 'Çıkarıldı';
ON CONFLICT (kayit_turu, durum) DO NOTHING;
